// Build the generated parts of the page: the browser import (src/core/atlas.js -> src/viewer/import.bundle.js) and the
// 3-D view (src/viewer/three/viewer3d.src.js + three.js -> src/viewer/viewer3d.bundle.js). Both are inlined into one
// offline HTML file, so they are strings, and a closing script tag inside one would end the page's script early.
import { build } from "esbuild";
import { createHash } from "node:crypto";
import { readFileSync, writeFileSync as write } from "node:fs";

// --check: build in memory and fail when a generated file differs from what the source and node_modules produce now
const check = process.argv.includes("--check"), stale = [];
const writeFileSync = (p, text) => { if (!check) return write(p, text); if (readFileSync(p, "utf8") !== text) stale.push(p.split("/src/").pop()); };

const at = (p) => new URL("../" + p, import.meta.url).pathname;
// in the page, the brain model is already inlined once (<script id="brain-shell">); the import code reads that copy
const shellFromPage = {
  name: "shell-from-page",
  setup(b) {
    b.onResolve({ filter: /\/brain-shell\.js$/ }, () => ({ path: "brain-shell-from-page", namespace: "page" }));
    b.onLoad({ filter: /.*/, namespace: "page" }, () => ({ contents: 'export const BRAIN_SHELL_B64 = (document.getElementById("brain-shell") || { textContent: "" }).textContent.trim();', loader: "js" }));
  },
};
const bundle = async (entry, globalName, plugins = []) => {
  const r = await build({ entryPoints: [at(entry)], bundle: true, format: "iife", globalName, minify: true, write: false, target: ["es2020"], legalComments: "eof", plugins });
  const js = r.outputFiles[0].text.replace(/<\/script/gi, "<\\/script");
  if (/\b__name\(/.test(js)) throw new Error(entry + ": the bundle calls a helper the page does not define");
  return { js, sha256: createHash("sha256").update(js).digest("hex") };
};
const imp = await bundle("src/core/atlas.js", "AtlasImport", [shellFromPage]);
writeFileSync(at("src/viewer/import.bundle.js"), `// GENERATED by scripts/build.mjs from src/core/atlas.js. Do not edit by hand.\nexport const IMPORT = ${JSON.stringify({ bytes: imp.js.length, sha256: imp.sha256 })};\nexport const IMPORT_JS = ${JSON.stringify(imp.js)};\n`);
const three = JSON.parse(readFileSync(at("node_modules/three/package.json"), "utf8")).version;
const v3 = await bundle("src/viewer/three/viewer3d.src.js", "Atlas3D");
writeFileSync(at("src/viewer/viewer3d.bundle.js"), `// GENERATED by scripts/build.mjs from src/viewer/three/viewer3d.src.js with three ${three} (MIT). Do not edit by hand.\nexport const VIEWER3D = ${JSON.stringify({ three, bytes: v3.js.length, sha256: v3.sha256 })};\nexport const VIEWER3D_JS = ${JSON.stringify(v3.js)};\n`);
if (check) {
  if (stale.length) { console.error(`stale generated files (run node scripts/build.mjs): src/${stale.join(", src/")}`); process.exit(1); }
  console.log("generated files are current");
} else console.log(JSON.stringify({ import: imp.js.length, viewer3d: v3.js.length, three }));
